await check('page 2 limit 2', () => callTool('catalog_search', { query: 'widget', offset: 2, limit: 2 }));

// 4. No matches
await check('no matches', () => callTool('catalog_search', { query: 'zzz' }));

// 5. Missing query
await check('missing query', () => callTool('catalog_search', {}));

// 6. Extra argument
await check('extra arg', () => callTool('catalog_search', { query: 'widget', foo: 1 }));

// 7. Limit out of range
await check('limit too big', () => callTool('catalog_search', { query: 'w', limit: 10 }));
await check('limit too small', () => callTool('catalog_search', { query: 'w', limit: 0 }));
await check('limit fractional', () => callTool('catalog_search', { query: 'w', limit: 1.5 }));

